const envUrl = process.env.SCALEKIT_ENV_URL || '';
const clientId = process.env.SCALEKIT_CLIENT_ID || '';
const clientSecret = process.env.SCALEKIT_CLIENT_SECRET || '';

const scalekit = new ScalekitClient(envUrl, clientId, clientSecret);

async function main() {
  const identifier = 'zealt-cleanup-test-999999';
  const connectionName = 'github-test';

  console.log('1. Creating/getting account...');
  const createRes = await scalekit.actions.getOrCreateConnectedAccount({
    connectionName,
    identifier
  });
  const acc = createRes.connectedAccount;
  if (!acc) {
    throw new Error('No connected account returned');
  }
  console.log(`Created account: connection=${connectionName} identifier=${acc.identifier} status=${ConnectorStatus[acc.status]}`);

  console.log('2. Listing connected accounts...');
  const listRes = await scalekit.actions.listConnectedAccounts({
    connectionName
  });
  const found = listRes.connectedAccounts?.find(a => a.identifier === identifier);
  console.log(`Listed: present=${!!found} identifier=${identifier}`);

  console.log('3. Deleting connected account...');
  await scalekit.actions.deleteConnectedAccount({
    connectionName,
